  "Browser storage read was denied; preferences remain usable in this page.": "브라우저 저장소 읽기가 거부되었습니다. 이 페이지 내에서는 환경설정을 계속 사용할 수 있습니다.",
  "Browser storage write was denied; changed preferences remain usable in this page.": "브라우저 저장소 쓰기가 거부되었습니다. 변경된 환경설정은 이 페이지 내에서 계속 사용할 수 있습니다.",
