  "Building a strip of {0} on {1} (Build {2}): {3}…": "{1}(빌드 {2})에서 {0} 스트립 빌드 중: {3}…",
  "Building a strip of {0} on {1}: {2} — remesh, compile and remesh's own check per value…": "{1}에서 {0} 스트립 빌드 중: {2} — 값별 리메시, 컴파일 및 리메시 자체 검사…",
  "Builds N values of the part's density field side by side, each as its own <code>replace /meshes/&lt;part&gt;</code> patch through remesh (into its own scratch folder). Rows are labels only: Load puts a row on the stage as pending, and the Mesh panel's Apply applies it. Closing or replacing the strip removes its scratch.": "파츠 밀도 필드의 N개 값을 각각 독립된 스크래치 폴더에 <code>replace /meshes/&lt;part&gt;</code> 패치로 remesh하여 나란히 빌드합니다. 각 행은 라벨일 뿐이며, 불러오기(Load)는 해당 행을 대기 상태로 스테이지에 올리고 메시 패널의 적용(Apply)이 실제로 적용합니다. 스트립을 닫거나 교체하면 해당 스크래치가 제거됩니다.",
  "Builds N values of the part's density field side by side, each as its own <code>replace /meshes/<part></code> patch through remesh (into its own scratch folder). Rows are labels only: Load puts a row on the stage as pending, and the Mesh panel's Apply applies it. Closing or replacing the strip removes its scratch.": "파츠 밀도 필드의 N개 값을 각각 독립된 스크래치 폴더에 <code>replace /meshes/&lt;part&gt;</code> 패치로 remesh하여 나란히 빌드합니다. 각 행은 라벨일 뿐이며, 불러오기(Load)는 해당 행을 대기 상태로 스테이지에 올리고 메시 패널의 적용(Apply)이 실제로 적용합니다. 스트립을 닫거나 교체하면 해당 스크래치가 제거됩니다.",
