  "CLOTH_KEYPOINTS_UNDECLARED: ": "CLOTH_KEYPOINTS_UNDECLARED: ",
  "CLOTH_KEYPOINTS_UNDECLARED: a cloth recipe Apply runs rig-parts propose, which places the body bones from the figure's keypoints; without them the draft moves the body bones the config states — declare the keypoint file with rig-review open <dir> --config <path> --keypoints <file> or the review.json \"producer\" block's \"keypoints\"": "CLOTH_KEYPOINTS_UNDECLARED: 천(Cloth) 레시피 적용은 인물의 키포인트로부터 신체 본을 배치하는 rig-parts propose를 실행합니다. 키포인트가 없으면 초안이 설정의 신체 본을 이동시키므로 rig-review open <dir> --config <path> --keypoints <file> 또는 review.json \"producer\" 블록의 \"keypoints\"로 키포인트 파일을 선언하세요",
  "CLOTH_NOTHING_PENDING: no pending ops": "CLOTH_NOTHING_PENDING: 보류 중인 작업이 없습니다",
  "CLOTH_PATCH_MIXED: ": "CLOTH_PATCH_MIXED: ",
