  "Click the part to place the armed landmark · drag a marker to move it · Space-drag pans": "파츠를 클릭하여 선택된 랜드마크 배치 · 마커를 드래그하여 이동 · Space+드래그로 화면 이동",
  "Click the part to place the cleavage; drag its marker to move it": "파츠를 클릭하여 클리비지를 배치하고 마커를 드래그하여 이동하세요",
