  "Crop height": "크롭 높이",
  "Crop pixels, x screen-right and y down (<code>family-chest-regions/1</code>). Place the circles with <strong>Chest regions</strong> in the view bar; this block holds names, bones, semi-axes, clip and the contour. Equal semi-axes export as a circle, unequal ones (or a clip) as the generator's 32-sample polygon. Exporting writes nothing into the package and is not an approval.": "크롭 픽셀 기준이며 x는 화면 오른쪽, y는 아래쪽입니다(<code>family-chest-regions/1</code>). 뷰 바의 <strong>가슴 영역</strong>으로 원을 배치하세요. 이 블록은 이름, 본, 반축, 클립 및 윤곽을 담습니다. 반축이 같으면 원으로, 다르거나 클립이 있으면 생성기의 32샘플 다각형으로 내보냅니다. 내보내기는 패키지에 아무것도 기록하지 않으며 승인이 아닙니다.",
  "Crop width": "크롭 너비",
