  "DENSITY_STRIP_BUSY: strip {0} is still running; close it when its candidates settle": "DENSITY_STRIP_BUSY: 스트립 {0}이(가) 아직 실행 중입니다. 후보가 완료되면 닫으세요",
  "DENSITY_STRIP_INPUT_CHECK_MISSING: the producer succeeded without an available regular input-check.json; no unrecorded retry was run": "DENSITY_STRIP_INPUT_CHECK_MISSING: 사용 가능한 일반 input-check.json 없이 프로듀서가 종료되었습니다. 기록되지 않은 재시도는 실행하지 않았습니다",
  "DENSITY_STRIP_LOAD_FAILED: {0}": "DENSITY_STRIP_LOAD_FAILED: {0}",
  "DENSITY_STRIP_ROW_NOT_LOADABLE: {0} — {1}": "DENSITY_STRIP_ROW_NOT_LOADABLE: {0} — {1}",
  "DOM images for rigid parts; WebGL meshes when available, Canvas2D fallback.": "리지드 파츠는 DOM 이미지, 가능한 경우 WebGL 메시(불가 시 Canvas2D 폴백)를 사용합니다.",
  "DOMAIN_PENDING: shared domain not established": "DOMAIN_PENDING: 공유 도메인이 설정되지 않았습니다",
  "DOMAIN_REFUSED: shared end is not finite": "DOMAIN_REFUSED: 공유 종료 시간이 유한하지 않습니다",
  "DOMAIN_REFUSED: {0}": "DOMAIN_REFUSED: {0}",
  "Dark": "다크",
  "Declare what the scene asks of the motion: a slot (picked on the stage), its mesh or a bone, an animation and a kind, with your own bar. Check writes a <code>spine-parts-requirements/1</code> file into scratch and runs the installed producer's <code>rig-parts check --requirements</code> on the inspected rig or the latest scratch build; each requirement gets one line with its worst frame (click to seek). A refusal is the producer's, by name. Waivers (<code>may_fold</code>), scene targets and the part exception lists are not written here. Submitted feedback carries the file by hash and content.": "장면이 모션에 요구하는 조건(스테이지에서 선택한 슬롯, 해당 메시 또는 본, 애니메이션, 종류 및 기준치)을 선언합니다. 점검(Check)은 스크래치에 <code>spine-parts-requirements/1</code> 파일을 작성하고 검사 대상 리그 또는 최신 스크래치 빌드에 대해 설치된 프로듀서의 <code>rig-parts check --requirements</code>를 실행합니다. 각 요구사항마다 최악 프레임이 포함된 한 줄이 표시됩니다(클릭하여 이동). 거부는 프로듀서의 코드명으로 표시됩니다. 면제(<code>may_fold</code>), 장면 타깃 및 파츠 예외 목록은 여기서 작성하지 않습니다. 제출된 피드백은 이 파일의 해시와 내용을 함께 전달합니다.",
  "Defaults apply to new inspections. Links and source drafts retain their explicit view.": "기본값은 새 검사에 적용됩니다. 링크와 소스 초안은 명시된 뷰를 유지합니다.",
  "Defect": "결함",
  "Degrees around the rest aim from the first stopped link's origin; pick a stop to drag its arc ends on the stage.": "첫 번째 제한된 링크의 원점에서 기본 조준 방향 기준 각도(°)입니다. 스톱을 선택하여 스테이지에서 호의 끝을 드래그하세요.",
  "Delete": "삭제",
  "Delete feedback with validation warnings, then add it again with a valid target.": "유효성 경고가 있는 피드백을 삭제한 뒤 유효한 대상으로 다시 추가하세요.",
  "Delete key": "키 삭제",
  "Delete {0} keys": "키 {0}개 삭제",
  "Delete · key X": "삭제 · 단축키 X",
  "Deleted {0} selected key(s) ({1} pending op(s)).": "선택한 키 {0}개 삭제됨 (보류 중인 작업 {1}개).",
  "Density strip candidate": "밀도 스트립 후보",
  "Describe the part, conditions and what looks wrong.": "파츠, 조건 및 무엇이 잘못되었는지 설명하세요.",
  "Designation is review evidence, not an approval. Nothing was written into the package; regeneration is the producer path.": "지정 데이터는 리뷰 근거 자료이며 승인이 아닙니다. 패키지에는 아무것도 기록되지 않았으며 재생성은 프로듀서 경로에서 수행합니다.",
  "Dial back to 0": "다이얼 0으로 복귀",
  "Discard conflicting local draft": "충돌하는 로컬 초안 폐기",
  "Discard pending": "대기 변경 버리기",
  "Discard unusable local draft": "사용할 수 없는 로컬 초안 폐기",
  "Discarded unapplied animation edits.": "적용되지 않은 애니메이션 편집을 폐기했습니다.",
  "Download JSON": "JSON 다운로드",
  "Download chest-regions.json": "chest-regions.json 다운로드",
  "Download chest-regions.json and its binding; evidence, not an approval": "chest-regions.json 및 바인딩 다운로드 (승인이 아닌 근거 자료)",
  "Download mesh-edit.json and its binding; evidence, not an approval": "mesh-edit.json 및 바인딩 다운로드 (승인이 아닌 근거 자료)",
  "Download saved local draft": "저장된 로컬 초안 다운로드",
