  "Downloaded chest-regions.json and chest-regions.binding.json. The regions are review evidence, not an approval; the package is unchanged.": "chest-regions.json 및 chest-regions.binding.json을 다운로드했습니다. 이 영역은 리뷰 근거 자료이며 승인이 아닙니다. 패키지는 변경되지 않습니다.",
  "Downloaded mesh-edit.json ({0} ops) and mesh-edit.binding.json for Build {1}.": "빌드 {1}의 mesh-edit.json(작업 {0}개) 및 mesh-edit.binding.json을 다운로드했습니다.",
  "Downloaded mesh-edit.json ({0} ops) and mesh-edit.binding.json. The delta is review evidence, not an approval; the package is unchanged and the producer retriangulates.": "mesh-edit.json(작업 {0}개) 및 mesh-edit.binding.json을 다운로드했습니다. 이 델타는 리뷰 근거 자료이며 승인이 아닙니다. 패키지는 변경되지 않으며 프로듀서가 재삼각분할합니다.",
  "Draft UI value invalid": "초안 UI 값이 유효하지 않음",
