  "MODELING_INPUT_UNAVAILABLE: ": "MODELING_INPUT_UNAVAILABLE: ",
  "MODELING_INPUT_UNAVAILABLE: source painting and See-through runs — rig-parts build reassembles the parts from the painting (--source) and the runs (--full, --head) before the rig, and the handoff declares none; declare them with rig-review open <dir> --config <path> --source <png> --full <dir> [--head <dir>] or the review.json \"producer\" block": "MODELING_INPUT_UNAVAILABLE: 소스 원화 및 투시(See-through) 실행 — rig-parts build는 리그 생성 전에 원화(--source)와 실행 결과(--full, --head)로부터 파츠를 재조립하지만 핸드오프에 선언되어 있지 않습니다. rig-review open <dir> --config <path> --source <png> --full <dir> [--head <dir>] 또는 review.json의 \"producer\" 블록으로 선언하세요",
  "MODELING_INPUT_UNAVAILABLE: source painting — propose --from-config reads the painting (--source) and the handoff declares none; declare it with rig-review open <dir> --config <path> --source <png> --full <dir> or the review.json \"producer\" block": "MODELING_INPUT_UNAVAILABLE: 소스 원화 — propose --from-config는 원화(--source)를 읽지만 핸드오프에 선언되어 있지 않습니다. rig-review open <dir> --config <path> --source <png> --full <dir> 또는 review.json의 \"producer\" 블록으로 선언하세요",
  "MODELING_INPUT_UNAVAILABLE: source painting — rig-parts propose reads the painting the parts were assembled from (--source), and the handoff declares none; declare it with rig-review open <dir> --config <path> --source <png> --full <dir> [--head <dir>] or the review.json \"producer\" block": "MODELING_INPUT_UNAVAILABLE: 소스 원화 — rig-parts propose는 파츠가 조립된 원화(--source)를 읽지만 핸드오프에 선언되어 있지 않습니다. rig-review open <dir> --config <path> --source <png> --full <dir> [--head <dir>] 또는 review.json의 \"producer\" 블록으로 선언하세요",
