  "PHYSICS_ROW_NOT_PHYSICS: config.constraints[{0}] is a {1} constraint; this panel tunes physics constraints only": "PHYSICS_ROW_NOT_PHYSICS: config.constraints[{0}]은(는) {1} 제약 조건입니다. 이 패널은 물리 제약 조건만 조정합니다",
