  "Put a pose sequence the package declares onto this rig: edit the <code>rig-pose-map/1</code> (per chain, the bone that carries each segment), set the clean and retarget flags, and Apply. The installed <code>@rig-c/pose</code> runs <code>rig-pose clean</code> and <code>rig-pose retarget</code> onto the handoff rig, and its <code>rigc</code> compiles the result, all into scratch; the new animation plays here beside the reference (pick the sequence under Reference). Review writes no keys and never writes the package's <code>motion.json</code>. Refusals (<code>POSE_NOT_CLEANED</code>, <code>POSE_BEND_ONE_WAY</code>, <code>RAISED_HEAD</code>, <code>MOTION_NAME_FREE</code>, <code>MAP_*</code>) are the producer's, verbatim. FEET, STANCE, FLIP, SHORT, END-ON, LEG-SCALE and REACH lines seek to their frame.": "패키지가 선언한 포즈 시퀀스를 이 리그에 입힙니다: <code>rig-pose-map/1</code>(체인별 각 세그먼트를 담당할 본)을 편집하고 클린 및 리타겟 플래그를 설정한 뒤 적용(Apply)하세요. 설치된 <code>@rig-c/pose</code>가 핸드오프 리그에 대해 <code>rig-pose clean</code>과 <code>rig-pose retarget</code>를 실행하고 <code>rigc</code>가 결과를 모두 스크래치로 컴파일합니다. 새 애니메이션은 레퍼런스 옆에서 재생됩니다(레퍼런스에서 시퀀스 선택). 리뷰 앱은 키를 직접 작성하지 않으며 패키지의 <code>motion.json</code>을 절대 수정하지 않습니다. 거부(<code>POSE_NOT_CLEANED</code>, <code>POSE_BEND_ONE_WAY</code>, <code>RAISED_HEAD</code>, <code>MOTION_NAME_FREE</code>, <code>MAP_*</code>)는 프로듀서 출력 그대로 표시됩니다. FEET, STANCE, FLIP, SHORT, END-ON, LEG-SCALE 및 REACH 라인은 클릭 시 해당 프레임으로 이동합니다.",
